head.b:skin:
/* ==============================================
   COMPLETE CSS - AUTO CONTENT BLOG TEMPLATE
   ============================================== */

* { margin:0; padding:0; box-sizing:border-box; }

:root {
  --primary: #1a1a2e;
  --secondary: #16213e;
  --accent: #e94560;
  --accent2: #0f3460;
  --bd-green: #006a4e;
  --bd-red: #f42a41;
  --text: #222222;
  --text-light: #666666;
  --bg: #f0f2f5;
  --white: #ffffff;
  --border: #e0e0e0;
  --shadow: 0 2px 12px rgba(0,0,0,0.08);
  --shadow-hover: 0 8px 30px rgba(0,0,0,0.15);
  --transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
  --radius: 12px;
  --nav-height: 52px;
}

[data-theme="dark"] {
  --primary: #0a0a0a;
  --secondary: #141414;
  --text: #e0e0e0;
  --text-light: #999999;
  --bg: #0f0f0f;
  --white: #1a1a1a;
  --border: #2a2a2a;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'Hind Siliguri', sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.7;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration:none; color:inherit; transition:var(--transition); }
img { max-width:100%; height:auto; display:block; }
button { font-family: inherit; }

/* ===== READING PROGRESS BAR ===== */
#readingProgress {
  position: fixed;
  top: 0;
  left: 0;
  width: 0%;
  height: 3px;
  background: linear-gradient(90deg, var(--bd-green), var(--accent), var(--bd-red));
  z-index: 99999;
  transition: width 0.15s;
}

/* ===== BREAKING NEWS TICKER ===== */
.breaking-news-bar {
  background: linear-gradient(135deg, #1a1a2e, #0f3460);
  color: white;
  padding: 0;
  font-size: 13px;
  font-weight: 500;
  overflow: hidden;
  border-bottom: 2px solid var(--accent);
}

.ticker-wrap {
  display: flex;
  align-items: center;
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 20px;
  height: 38px;
}

.breaking-label {
  background: var(--bd-red);
  padding: 4px 14px;
  border-radius: 3px;
  font-weight: 800;
  text-transform: uppercase;
  font-size: 10px;
  letter-spacing: 1.5px;
  white-space: nowrap;
  margin-right: 10px;
  animation: blink 1.5s infinite;
  flex-shrink: 0;
}

@keyframes blink {
  0%,100% { opacity:1; }
  50% { opacity:0.6; }
}

.ticker-tabs {
  display: flex;
  gap: 4px;
  margin-right: 12px;
  flex-shrink: 0;
}

.ticker-tab {
  background: rgba(255,255,255,0.1);
  color: white;
  border: 1px solid rgba(255,255,255,0.2);
  padding: 2px 10px;
  border-radius: 3px;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: var(--transition);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ticker-tab:hover, .ticker-tab.active {
  background: var(--accent);
  border-color: var(--accent);
}

.ticker-content-wrapper {
  flex: 1;
  overflow: hidden;
  position: relative;
  height: 38px;
  display: flex;
  align-items: center;
}

.ticker-content {
  display: flex;
  animation: ticker 30s linear infinite;
  white-space: nowrap;
}

.ticker-content:hover { animation-play-state: paused; }

.ticker-content span {
  padding: 0 25px;
  flex-shrink: 0;
}

.ticker-content a {
  color: white !important;
  text-decoration: none !important;
  font-size: 13px;
}

.ticker-content a:hover {
  color: #ffd700 !important;
}

@keyframes ticker {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== TOP BAR ===== */
.top-bar {
  background: var(--primary);
  color: rgba(255,255,255,0.85);
  padding: 6px 0;
  font-size: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.top-bar .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.top-bar-left, .top-bar-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.top-bar a { color: rgba(255,255,255,0.75); font-size: 12px; }
.top-bar a:hover { color: var(--accent); }

.dark-toggle {
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  color: white;
  padding: 3px 10px;
  border-radius: 15px;
  cursor: pointer;
  font-size: 11px;
  transition: var(--transition);
}

.dark-toggle:hover {
  background: var(--accent);
  border-color: var(--accent);
}

/* ===== HEADER ===== */
.main-header {
  background: var(--white);
  padding: 18px 0;
  border-bottom: 4px solid;
  border-image: linear-gradient(90deg, var(--bd-green), var(--accent), var(--bd-red)) 1;
  box-shadow: var(--shadow);
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 15px;
}

.logo h1 {
  font-family: 'Merriweather', serif;
  font-size: clamp(22px, 4vw, 36px);
  font-weight: 900;
  color: var(--primary);
  letter-spacing: -1px;
  line-height: 1.2;
}

.logo h1 span { color: var(--accent); }
.logo .tagline {
  font-size: 12px;
  color: var(--text-light);
  font-weight: 400;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.header-search { position: relative; }

.header-search input {
  padding: 10px 40px 10px 15px;
  border: 2px solid var(--border);
  border-radius: 25px;
  font-size: 13px;
  width: clamp(180px, 25vw, 280px);
  background: var(--bg);
  color: var(--text);
  transition: var(--transition);
}

.header-search input:focus {
  border-color: var(--accent);
  outline: none;
  box-shadow: 0 0 0 3px rgba(233,69,96,0.1);
}

.header-search button {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: var(--text-light);
  cursor: pointer;
  font-size: 14px;
}

/* ===== NAVIGATION ===== */
.main-nav {
  background: var(--secondary);
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: 0 2px 15px rgba(0,0,0,0.3);
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 20px;
  position: relative;
}

.nav-menu {
  display: flex;
  list-style: none;
  flex-wrap: wrap;
}

.nav-menu li { position: relative; }

.nav-menu > li > a {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 14px 16px;
  color: white;
  font-weight: 500;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: var(--transition);
  white-space: nowrap;
}

.nav-menu > li > a i { font-size: 11px; }
.nav-menu > li > a:hover,
.nav-menu > li > a.active { background: var(--accent); }

.nav-menu li .dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  background: var(--white);
  min-width: 220px;
  box-shadow: var(--shadow-hover);
  border-radius: 0 0 8px 8px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: var(--transition);
  z-index: 100;
}

.nav-menu li:hover .dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.dropdown a {
  display: block;
  padding: 10px 18px;
  color: var(--text);
  font-size: 13px;
  border-bottom: 1px solid var(--border);
  text-transform: none;
}

.dropdown a:hover { background: var(--accent); color: white; }

.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: white;
  font-size: 22px;
  cursor: pointer;
  padding: 10px;
}

/* ===== CONTAINER ===== */
.container {
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 20px;
}

/* ===== SECTION HEADERS ===== */
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 30px 0 20px;
  padding-bottom: 12px;
  border-bottom: 3px solid var(--accent);
}

.section-header h2 {
  font-family: 'Merriweather', serif;
  font-size: clamp(18px, 3vw, 24px);
  font-weight: 700;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 8px;
}

.section-header .view-all {
  font-size: 13px;
  color: var(--accent);
  font-weight: 600;
  white-space: nowrap;
}

.section-header .view-all:hover { text-decoration: underline; }

/* ===== AUTO CONTENT CARDS ===== */
.auto-news-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
  margin-bottom: 30px;
}

.auto-card {
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.auto-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-hover);
}

.auto-card .card-img {
  position: relative;
  height: 180px;
  overflow: hidden;
  background: linear-gradient(135deg, var(--primary), var(--accent2));
}

.auto-card .card-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.auto-card:hover .card-img img { transform: scale(1.08); }

.auto-card .card-img .source-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--accent);
  color: white;
  padding: 3px 10px;
  border-radius: 3px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.auto-card .card-img .time-badge {
  position: absolute;
  bottom: 10px;
  right: 10px;
  background: rgba(0,0,0,0.7);
  color: white;
  padding: 3px 8px;
  border-radius: 3px;
  font-size: 10px;
}

.auto-card .card-body {
  padding: 15px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.auto-card .card-body h3 {
  font-family: 'Merriweather', serif;
  font-size: 15px;
  line-height: 1.4;
  margin-bottom: 8px;
  color: var(--text);
  flex: 1;
}

.auto-card .card-body h3:hover { color: var(--accent); }

.auto-card .card-body p {
  font-size: 13px;
  color: var(--text-light);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 10px;
}

.auto-card .card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  color: var(--text-light);
  padding-top: 10px;
  border-top: 1px solid var(--border);
}

.auto-card .card-footer .source {
  color: var(--accent);
  font-weight: 600;
}

/* Loading Skeleton */
.skeleton-card {
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}

.skeleton-img {
  height: 180px;
  background: linear-gradient(90deg, var(--border) 25%, var(--bg) 50%, var(--border) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}

.skeleton-text {
  height: 14px;
  background: linear-gradient(90deg, var(--border) 25%, var(--bg) 50%, var(--border) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
  border-radius: 4px;
  margin: 10px 15px;
}

.skeleton-text.short { width: 60%; }
.skeleton-text.medium { width: 80%; }

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

/* ===== FEATURED HERO (HOMEPAGE) ===== */
.featured-hero {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  grid-template-rows: 200px 200px;
  gap: 15px;
  margin: 25px 0;
}

.hero-item {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
}

.hero-item:first-child { grid-row: 1 / 3; }

.hero-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s ease;
}

.hero-item:hover img { transform: scale(1.05); }

.hero-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 25px;
  background: linear-gradient(transparent, rgba(0,0,0,0.85));
  color: white;
}

.hero-overlay .badge {
  display: inline-block;
  background: var(--accent);
  padding: 3px 10px;
  border-radius: 3px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 8px;
}

.hero-overlay h2 {
  font-family: 'Merriweather', serif;
  font-size: clamp(14px, 2.5vw, 24px);
  line-height: 1.3;
}

.hero-overlay .meta {
  font-size: 11px;
  opacity: 0.8;
  margin-top: 5px;
}

/* ===== MY POSTS GRID (HOMEPAGE) ===== */
.my-posts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 25px;
}

.post-card {
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: var(--transition);
}

.post-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-hover);
}

.post-card .post-thumb {
  position: relative;
  height: 200px;
  overflow: hidden;
}

.post-card .post-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.post-card:hover .post-thumb img { transform: scale(1.1); }

.post-thumb .category-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--accent);
  color: white;
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.post-card .post-content { padding: 18px; }

.post-card h3 {
  font-family: 'Merriweather', serif;
  font-size: 17px;
  line-height: 1.4;
  margin-bottom: 8px;
  color: var(--text);
}

.post-card h3:hover { color: var(--accent); }

.post-excerpt {
  font-size: 13px;
  color: var(--text-light);
  line-height: 1.6;
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-light);
  padding-top: 12px;
  border-top: 1px solid var(--border);
}

.post-meta .author {
  display: flex;
  align-items: center;
  gap: 6px;
}

.post-meta .author img {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  object-fit: cover;
}

/* ===== MAIN LAYOUT ===== */
.main-content {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 30px;
  padding: 20px 0;
}

/* ===== SIDEBAR ===== */
.sidebar {
  position: sticky;
  top: 65px;
  height: fit-content;
}

.widget {
  background: var(--white);
  border-radius: var(--radius);
  padding: 20px;
  margin-bottom: 20px;
  box-shadow: var(--shadow);
}

.widget-title {
  font-family: 'Merriweather', serif;
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 15px;
  padding-bottom: 10px;
  border-bottom: 3px solid var(--accent);
  display: flex;
  align-items: center;
  gap: 6px;
}

/* Sidebar News Items */
.news-item {
  display: flex;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
  transition: var(--transition);
}

.news-item:hover { padding-left: 4px; }
.news-item:last-child { border-bottom: none; }

.news-item .news-num {
  font-size: 20px;
  font-weight: 900;
  color: var(--accent);
  font-family: 'Merriweather', serif;
  line-height: 1;
  min-width: 25px;
}

.news-item h4 {
  font-size: 12px;
  line-height: 1.4;
  font-weight: 600;
  color: var(--text);
}

.news-item h4:hover { color: var(--accent); }

.news-item .news-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 3px;
}

.news-item .news-source {
  font-size: 10px;
  color: var(--accent);
  font-weight: 600;
}

.news-item .news-time {
  font-size: 10px;
  color: var(--text-light);
}

.live-refresh-btn {
  display: block;
  width: 100%;
  padding: 7px;
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-weight: 600;
  font-size: 11px;
  transition: var(--transition);
  margin-top: 8px;
}

.live-refresh-btn:hover { background: var(--primary); }

/* Social Links */
.social-links {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.social-link {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px;
  border-radius: 6px;
  color: white;
  font-size: 12px;
  font-weight: 600;
  transition: var(--transition);
}

.social-link:hover { transform: translateY(-2px); filter: brightness(1.1); }
.social-link.facebook { background: #1877f2; }
.social-link.twitter { background: #000000; }
.social-link.youtube { background: #ff0000; }
.social-link.instagram { background: linear-gradient(45deg,#f09433,#dc2743,#bc1888); }
.social-link.telegram { background: #0088cc; }
.social-link.whatsapp { background: #25d366; }

/* Newsletter */
.newsletter-widget {
  background: linear-gradient(135deg, var(--primary), var(--accent2));
  color: white;
  text-align: center;
}

.newsletter-widget .widget-title { color: white; border-color: var(--accent); }
.newsletter-widget p { font-size: 13px; margin-bottom: 12px; opacity: 0.9; }

.newsletter-widget input[type="email"] {
  width: 100%;
  padding: 10px;
  border: none;
  border-radius: 6px;
  margin-bottom: 8px;
  font-size: 13px;
}

.newsletter-widget button {
  width: 100%;
  padding: 10px;
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 6px;
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  transition: var(--transition);
}

.newsletter-widget button:hover { background: #d63447; }

/* Tags */
.tags-cloud { display: flex; flex-wrap: wrap; gap: 6px; }

.tag-item {
  padding: 4px 10px;
  background: var(--bg);
  border-radius: 15px;
  font-size: 11px;
  color: var(--text-light);
  transition: var(--transition);
}

.tag-item:hover { background: var(--accent); color: white; }

/* ===== SINGLE POST PAGE ===== */
.post-page { max-width: 800px; }
.post-page .post-header { margin-bottom: 25px; }

.post-page .post-header .category-badge {
  display: inline-block;
  background: var(--accent);
  color: white;
  padding: 4px 14px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 12px;
}

.post-page h1.post-title {
  font-family: 'Merriweather', serif;
  font-size: clamp(24px, 4vw, 36px);
  line-height: 1.3;
  margin-bottom: 12px;
  color: var(--text);
}

.post-page .post-body {
  font-size: 17px;
  line-height: 1.9;
  color: var(--text);
}

.post-page .post-body h2 {
  font-family: 'Merriweather', serif;
  font-size: 24px;
  margin: 28px 0 14px;
}

.post-page .post-body h3 {
  font-family: 'Merriweather', serif;
  font-size: 20px;
  margin: 22px 0 10px;
}

.post-page .post-body p { margin-bottom: 18px; }

.post-page .post-body blockquote {
  border-left: 4px solid var(--accent);
  padding: 18px 22px;
  margin: 22px 0;
  background: var(--bg);
  border-radius: 0 8px 8px 0;
  font-style: italic;
  font-size: 17px;
}

.post-page .post-body img { border-radius: var(--radius); margin: 18px 0; }

/* Share Buttons */
.share-buttons {
  display: flex;
  gap: 8px;
  padding: 20px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  margin: 22px 0;
  flex-wrap: wrap;
}

.share-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 7px 14px;
  border-radius: 5px;
  color: white;
  font-size: 12px;
  font-weight: 600;
  transition: var(--transition);
  border: none;
  cursor: pointer;
}

.share-btn:hover { transform: translateY(-2px); }
.share-btn.fb { background: #1877f2; }
.share-btn.tw { background: #000; }
.share-btn.wa { background: #25d366; }
.share-btn.li { background: #0077b5; }
.share-btn.tg { background: #0088cc; }
.share-btn.copy { background: var(--text-light); }

/* Author Box */
.author-box {
  display: flex;
  gap: 18px;
  background: var(--bg);
  padding: 22px;
  border-radius: var(--radius);
  margin: 25px 0;
}

.author-box img { width: 70px; height: 70px; border-radius: 50%; object-fit: cover; }
.author-box h4 { font-size: 16px; margin-bottom: 4px; }
.author-box p { font-size: 13px; color: var(--text-light); line-height: 1.5; }

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  gap: 8px;
  padding: 25px 0;
}

.pagination a {
  padding: 8px 14px;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-weight: 600;
  font-size: 13px;
  color: var(--text);
  transition: var(--transition);
}

.pagination a:hover { background: var(--accent); color: white; border-color: var(--accent); }

/* ===== BACK TO TOP ===== */
.back-to-top {
  position: fixed;
  bottom: 25px;
  right: 25px;
  background: var(--accent);
  color: white;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  cursor: pointer;
  border: none;
  box-shadow: var(--shadow-hover);
  opacity: 0;
  visibility: hidden;
  transition: var(--transition);
  z-index: 999;
}

.back-to-top.visible { opacity:1; visibility:visible; }
.back-to-top:hover { transform:translateY(-3px); background:var(--primary); }

/* ===== FOOTER ===== */
.main-footer {
  background: var(--primary);
  color: white;
  padding: 45px 0 0;
  margin-top: 30px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 25px;
  padding-bottom: 35px;
}

.footer-section h3 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 15px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--accent);
  display: inline-block;
}

.footer-section p {
  font-size: 13px;
  color: rgba(255,255,255,0.7);
  line-height: 1.7;
}

.footer-links { list-style: none; }
.footer-links li { margin-bottom: 8px; }

.footer-links a {
  color: rgba(255,255,255,0.7);
  font-size: 13px;
  transition: var(--transition);
}

.footer-links a:hover { color: var(--accent); padding-left: 4px; }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding: 15px 0;
  text-align: center;
  font-size: 12px;
  color: rgba(255,255,255,0.4);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .main-content { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  .featured-hero { grid-template-columns: 1fr; grid-template-rows: auto; }
  .featured-hero .hero-item:first-child { grid-row: auto; }
}

@media (max-width: 768px) {
  .menu-toggle { display: block; }
  .nav-menu {
    display: none;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--secondary);
    box-shadow: var(--shadow-hover);
    max-height: 80vh;
    overflow-y: auto;
  }
  .nav-menu.active { display: flex; }
  .nav-menu li .dropdown {
    position: static;
    opacity: 1;
    visibility: visible;
    transform: none;
    box-shadow: none;
    background: rgba(0,0,0,0.2);
  }
  .dropdown a { color: white; border-color: rgba(255,255,255,0.1); }
  .my-posts-grid { grid-template-columns: 1fr; }
  .auto-news-grid { grid-template-columns: 1fr; }
  .header-content { justify-content: center; text-align: center; }
  .top-bar { display: none; }
  .ticker-tabs { display: none; }
  .social-links { grid-template-columns: 1fr; }
  .share-buttons { justify-content: center; }
  .author-box { flex-direction: column; text-align: center; align-items: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 12px; }
  .widget { padding: 15px; }
  .auto-news-grid { grid-template-columns: 1fr; }
}

@media print {
  .main-nav, .sidebar, .share-buttons, .main-footer,
  .back-to-top, .breaking-news-bar, .top-bar,
  .auto-content-section { display:none; }
  .main-content { grid-template-columns: 1fr; }
}

body.script:
//

// ==================================================
// CONFIGURATION — CHANGE YOUR NEWS QUERIES HERE
// ==================================================
var NEWS_CONFIG = {
  bdpolitics: {
    title: '🇧🇩 Bangladesh Politics',
    icon: 'fas fa-landmark',
    query: 'Bangladesh+politics',
    rssUrl: 'https://news.google.com/rss/search?q=Bangladesh+politics+when:2d&hl=en-BD&gl=BD&ceid=BD:en',
    color: '#006a4e'
  },
  international: {
    title: '🌍 International News',
    icon: 'fas fa-globe-americas',
    query: 'world+news',
    rssUrl: 'https://news.google.com/rss/topics/WORLD?hl=en&gl=US&ceid=US:en',
    color: '#0f3460'
  },
  opinion: {
    title: '💬 Opinion & Analysis',
    icon: 'fas fa-comment-dots',
    query: 'opinion+editorial+analysis',
    rssUrl: 'https://news.google.com/rss/search?q=Bangladesh+opinion+editorial+when:3d&hl=en-BD&gl=BD&ceid=BD:en',
    color: '#8e44ad'
  },
  economy: {
    title: '💰 Economy & Business',
    icon: 'fas fa-chart-line',
    query: 'Bangladesh+economy+business',
    rssUrl: 'https://news.google.com/rss/search?q=Bangladesh+economy+business+when:2d&hl=en-BD&gl=BD&ceid=BD:en',
    color: '#e67e22'
  },
  technology: {
    title: '🔬 Technology',
    icon: 'fas fa-microchip',
    query: 'technology+AI+digital',
    rssUrl: 'https://news.google.com/rss/topics/TECHNOLOGY?hl=en&gl=US&ceid=US:en',
    color: '#2980b9'
  },
  sports: {
    title: '⚽ Sports',
    icon: 'fas fa-futbol',
    query: 'Bangladesh+cricket+sports',
    rssUrl: 'https://news.google.com/rss/search?q=Bangladesh+sports+cricket+when:2d&hl=en-BD&gl=BD&ceid=BD:en',
    color: '#27ae60'
  }
};

var RSS2JSON_BASE = 'https://api.rss2json.com/v1/api.json?rss_url=';

// ==================================================
// UTILITY FUNCTIONS
// ==================================================
function getTimeAgo(dateStr) {
  var s = Math.floor((new Date() - new Date(dateStr)) / 1000);
  if (s < 60) return 'Just now';
  if (s < 3600) return Math.floor(s / 60) + 'm ago';
  if (s < 86400) return Math.floor(s / 3600) + 'h ago';
  return Math.floor(s / 86400) + 'd ago';
}

function getSource(title) {
  var m = title.match(/\s*-\s*([^-]+)$/);
  return m ? m[1].trim() : 'News';
}

function cleanTitle(title) {
  return title.replace(/\s*-\s*[^-]+$/, '');
}

function extractImage(item) {
  if (item.thumbnail && item.thumbnail.length > 10) return item.thumbnail;
  if (item.enclosure && item.enclosure.link) return item.enclosure.link;
  var match = (item.description || '').match(/<img[^>]+src="([^"]+)"/);
  if (match) return match[1];
  // Generate colored placeholder based on category
  return 'https://via.placeholder.com/600x400/1a1a2e/ffffff?text=' + 
         encodeURIComponent(cleanTitle(item.title).substring(0, 30));
}

// ==================================================
// MOBILE MENU
// ==================================================
function toggleMenu() {
  document.getElementById('navMenu').classList.toggle('active');
}

// Close menu when clicking outside
document.addEventListener('click', function(e) {
  var nav = document.querySelector('.main-nav');
  var menu = document.getElementById('navMenu');
  if (menu && menu.classList.contains('active') && !nav.contains(e.target)) {
    menu.classList.remove('active');
  }
});

// ==================================================
// DARK MODE
// ==================================================
function toggleDarkMode() {
  var isDark = document.body.getAttribute('data-theme') === 'dark';
  document.body.setAttribute('data-theme', isDark ? 'light' : 'dark');
  localStorage.setItem('theme', isDark ? 'light' : 'dark');
}
(function() {
  var saved = localStorage.getItem('theme');
  if (saved) document.body.setAttribute('data-theme', saved);
})();

// ==================================================
// DATE DISPLAY
// ==================================================
(function() {
  var el = document.getElementById('dateDisplay');
  if (el) {
    el.innerHTML = '<i class="far fa-calendar"></i> ' + 
      new Date().toLocaleDateString('en-US', {
        weekday:'long', year:'numeric', month:'long', day:'numeric'
      });
  }
})();

// ==================================================
// BACK TO TOP + READING PROGRESS
// ==================================================
window.addEventListener('scroll', function() {
  var btn = document.getElementById('backToTop');
  if (window.scrollY > 300) btn.classList.add('visible');
  else btn.classList.remove('visible');

  // Reading progress
  var prog = document.getElementById('readingProgress');
  if (prog) {
    var scrollTop = window.scrollY;
    var docHeight = document.documentElement.scrollHeight - window.innerHeight;
    prog.style.width = (docHeight > 0 ? (scrollTop / docHeight * 100) : 0) + '%';
  }
});

function scrollToTop() {
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// ==================================================
// COPY LINK
// ==================================================
function copyLink(el) {
  var url = el.getAttribute('data-url') || window.location.href;
  navigator.clipboard.writeText(url).then(function() {
    el.innerHTML = '<i class="fas fa-check"></i> Copied!';
    setTimeout(function() {
      el.innerHTML = '<i class="fas fa-link"></i> Copy';
    }, 2000);
  });
}

// ==================================================
// BREAKING NEWS TICKER
// ==================================================
(function() {
  var tickerSources = {
    bd: 'https://news.google.com/rss/search?q=Bangladesh+politics+when:1d&hl=en-BD&gl=BD&ceid=BD:en',
    intl: 'https://news.google.com/rss/topics/WORLD?hl=en&gl=US&ceid=US:en'
  };
  var currentCat = 'bd';
  var autoTimer;

  function fetchTicker(cat) {
    var url = RSS2JSON_BASE + encodeURIComponent(tickerSources[cat]) + '&count=10';
    var ticker = document.getElementById('breakingTicker');
    if (!ticker) return;

    fetch(url)
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data.status === 'ok' && data.items && data.items.length > 0) {
          var html = '';
          data.items.forEach(function(item) {
            var title = cleanTitle(item.title);
            html += '<span><a href="' + item.link + '" target="_blank" rel="noopener">● ' + title + '</a></span>';
          });
          ticker.innerHTML = html + html;
        }
      })
      .catch(function() {
        ticker.innerHTML = '<span>📰 Stay tuned for breaking news</span>';
      });
  }

  window.switchTicker = function(cat) {
    currentCat = cat;
    document.querySelectorAll('.ticker-tab').forEach(function(t) { t.classList.remove('active'); });
    document.getElementById(cat === 'bd' ? 'tabBD' : 'tabIntl').classList.add('active');
    fetchTicker(cat);
    clearInterval(autoTimer);
    autoTimer = setInterval(function() {
      currentCat = currentCat === 'bd' ? 'intl' : 'bd';
      window.switchTicker(currentCat);
    }, 60000);
  };

  fetchTicker('bd');
  autoTimer = setInterval(function() {
    currentCat = currentCat === 'bd' ? 'intl' : 'bd';
    window.switchTicker(currentCat);
  }, 60000);
})();

// ==================================================
// SIDEBAR NEWS WIDGETS
// ==================================================
function renderSidebarNews(items) {
  var html = '';
  items.forEach(function(item, i) {
    html += '<div class="news-item">'
          + '<span class="news-num">' + (i + 1) + '</span>'
          + '<div>'
          + '<a href="' + item.link + '" target="_blank" rel="noopener">'
          + '<h4>' + cleanTitle(item.title) + '</h4></a>'
          + '<div class="news-meta">'
          + '<span class="news-source">' + getSource(item.title) + '</span>'
          + '<span class="news-time">' + getTimeAgo(item.pubDate) + '</span>'
          + '</div></div></div>';
  });
  return html;
}

function loadSidebarBD() {
  var url = RSS2JSON_BASE + encodeURIComponent(NEWS_CONFIG.bdpolitics.rssUrl) + '&count=5';
  var containers = document.querySelectorAll('[id^="bdPoliticsWidget"], [id="bdWidgetAuto"]');
  containers.forEach(function(c) { c.innerHTML = '<p style="font-size:12px;color:var(--text-light);">Loading...</p>'; });

  fetch(url)
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data.status === 'ok' && data.items) {
        var html = renderSidebarNews(data.items);
        containers.forEach(function(c) { c.innerHTML = html; });
      }
    })
    .catch(function() {
      containers.forEach(function(c) { c.innerHTML = '<p style="font-size:12px;color:var(--text-light);">Failed</p>'; });
    });
}

function loadSidebarIntl() {
  var url = RSS2JSON_BASE + encodeURIComponent(NEWS_CONFIG.international.rssUrl) + '&count=5';
  var containers = document.querySelectorAll('[id^="intlNewsWidget"], [id="intlWidgetAuto"]');
  containers.forEach(function(c) { c.innerHTML = '<p style="font-size:12px;color:var(--text-light);">Loading...</p>'; });

  fetch(url)
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data.status === 'ok' && data.items) {
        var html = renderSidebarNews(data.items);
        containers.forEach(function(c) { c.innerHTML = html; });
      }
    })
    .catch(function() {
      containers.forEach(function(c) { c.innerHTML = '<p style="font-size:12px;color:var(--text-light);">Failed</p>'; });
    });
}

// ==================================================
// AUTO CONTENT — MAIN NEWS CARDS
// ==================================================
function renderAutoCards(items, color) {
  var html = '';
  items.forEach(function(item) {
    var title = cleanTitle(item.title);
    var source = getSource(item.title);
    var time = getTimeAgo(item.pubDate);
    var img = extractImage(item);
    var desc = (item.description || '').replace(/<[^>]*>/g, '').substring(0, 120);

    html += '<article class="auto-card">'
          + '<a href="' + item.link + '" target="_blank" rel="noopener" class="card-img">'
          + '<img src="' + img + '" alt="' + title.substring(0,50) + '" '
          + 'onerror="this.src=\'https://via.placeholder.com/600x400/1a1a2e/fff?text=News\'" />'
          + '<span class="source-badge" style="background:' + (color || 'var(--accent)') + ';">' + source + '</span>'
          + '<span class="time-badge">' + time + '</span>'
          + '</a>'
          + '<div class="card-body">'
          + '<a href="' + item.link + '" target="_blank" rel="noopener"><h3>' + title + '</h3></a>'
          + '<p>' + desc + '</p>'
          + '<div class="card-footer">'
          + '<span class="source">' + source + '</span>'
          + '<span>' + time + '</span>'
          + '</div></div></article>';
  });
  return html;
}

function loadAutoContent(containerId, rssUrl, count, color) {
  var url = RSS2JSON_BASE + encodeURIComponent(rssUrl) + '&count=' + (count || 9);
  var container = document.getElementById(containerId);
  if (!container) return;

  fetch(url)
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data.status === 'ok' && data.items && data.items.length > 0) {
        container.innerHTML = renderAutoCards(data.items, color);
      } else {
        container.innerHTML = '<p style="padding:40px;text-align:center;color:var(--text-light);">No articles found. Try again later.</p>';
      }
    })
    .catch(function() {
      container.innerHTML = '<p style="padding:40px;text-align:center;color:var(--text-light);">⚠️ Unable to load content. Please refresh.</p>';
    });
}

// ==================================================
// SHOW / HIDE AUTO CONTENT SECTIONS
// ==================================================
function showAutoSection(categoryKey) {
  var config = NEWS_CONFIG[categoryKey];
  if (!config) return;

  // Close mobile menu
  var menu = document.getElementById('navMenu');
  if (menu) menu.classList.remove('active');

  // Hide blogger content, show auto content
  var blogContent = document.getElementById('bloggerContent');
  var autoContent = document.getElementById('autoContentSection');
  if (blogContent) blogContent.style.display = 'none';
  if (autoContent) autoContent.style.display = 'block';

  // Update title
  var titleEl = document.getElementById('autoSectionTitle');
  if (titleEl) {
    titleEl.innerHTML = '<i class="' + config.icon + '"></i> ' + config.title;
  }

  // Load content
  loadAutoContent('autoNewsGrid', config.rssUrl, 12, config.color);

  // Load sidebar
  loadSidebarBD();
  loadSidebarIntl();

  // Scroll to top
  window.scrollTo({ top: 0, behavior: 'smooth' });

  // Update active nav
  document.querySelectorAll('.nav-menu > li > a').forEach(function(a) {
    a.classList.remove('active');
  });
}

function hideAutoSection() {
  var blogContent = document.getElementById('bloggerContent');
  var autoContent = document.getElementById('autoContentSection');
  if (blogContent) blogContent.style.display = 'block';
  if (autoContent) autoContent.style.display = 'none';
  window.scrollTo({ top: 0, behavior: 'smooth' });

  // Reset nav active
  document.querySelectorAll('.nav-menu > li > a').forEach(function(a) {
    a.classList.remove('active');
  });
  var homeLink = document.querySelector('.nav-menu > li:first-child > a');
  if (homeLink) homeLink.classList.add('active');
}

// Load custom feed from dropdown
function loadCustomFeed(id, query) {
  var rssUrl = 'https://news.google.com/rss/search?q=' + query + '+when:2d&hl=en&gl=BD&ceid=BD:en';

  // Close mobile menu
  var menu = document.getElementById('navMenu');
  if (menu) menu.classList.remove('active');

  var blogContent = document.getElementById('bloggerContent');
  var autoContent = document.getElementById('autoContentSection');
  if (blogContent) blogContent.style.display = 'none';
  if (autoContent) autoContent.style.display = 'block';

  var titleEl = document.getElementById('autoSectionTitle');
  if (titleEl) titleEl.innerHTML = '<i class="fas fa-newspaper"></i> ' + query.replace(/\+/g, ' ');

  loadAutoContent('autoNewsGrid', rssUrl, 12, 'var(--accent)');
  loadSidebarBD();
  loadSidebarIntl();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// ==================================================
// HOMEPAGE AUTO SECTIONS (BD, Intl, Economy previews)
// ==================================================
function loadHomeAutoSections() {
  loadAutoContent('homeBDGrid', NEWS_CONFIG.bdpolitics.rssUrl, 3, NEWS_CONFIG.bdpolitics.color);
  loadAutoContent('homeIntlGrid', NEWS_CONFIG.international.rssUrl, 3, NEWS_CONFIG.international.color);
  loadAutoContent('homeEconGrid', NEWS_CONFIG.economy.rssUrl, 3, NEWS_CONFIG.economy.color);
}

// ==================================================
// READING TIME (Single Post)
// ==================================================
function addReadingTime() {
  var body = document.querySelector('.post-body');
  if (body) {
    var words = body.textContent.trim().split(/\s+/).length;
    var mins = Math.ceil(words / 200);
    var el = document.createElement('span');
    el.style.cssText = 'font-size:12px;color:var(--text-light);margin-left:12px;';
    el.innerHTML = '<i class="far fa-clock"></i> ' + mins + ' min read';
    var meta = document.querySelector('.post-page .post-meta');
    if (meta) meta.appendChild(el);
  }
}

// ==================================================
// INITIALIZE EVERYTHING
// ==================================================
function initAll() {
  loadSidebarBD();
  loadSidebarIntl();
  loadHomeAutoSections();
  addReadingTime();
}

// Run on load
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initAll);
} else {
  initAll();
}

// Auto refresh sidebar every 5 minutes
setInterval(function() {
  loadSidebarBD();
  loadSidebarIntl();
}, 300000);

//
